mapper.select:
SELECT id, open_id, phone, email, nickname, avatar_url, enabled, created_at, updated_at
FROM wx_user
WHERE id = #{id}

SELECT id, open_id, nickname, avatar_url, enabled, created_at, updated_at
FROM wx_user
WHERE open_id = #{openId}

SELECT id, open_id, nickname, avatar_url, enabled, created_at, updated_at FROM wx_user
nickname LIKE CONCAT('%', #{keyword}, '%') OR open_id LIKE CONCAT('%', #{keyword}, '%') OR CAST(id AS CHAR) LIKE CONCAT('%', #{keyword}, '%')
ORDER BY updated_at DESC, id DESC LIMIT #{size} OFFSET #{offset}
